/**
 * Guard: this plugin's shared modules must match `shared/` byte for byte.
 *
 * WHY. `lib/define.js` is not authored in this plugin: it is a copy of
 * `shared/define.js`, generated by `node tools/sync-shared-code.mjs`. Before that
 * tool existed, four plugins each carried a hand-maintained copy: they happened
 * to be identical, but nothing prevented one from being edited and silently
 * diverging, and a divergence in a schema compiler is the kind of bug that shows
 * up as "the model's arguments are rejected for no reason" long after the change.
 *
 * The runtime copy must exist (a `link:` plugin cannot reliably import from the
 * workspace root: there is no node_modules there), so the copy stays and this
 * test makes the duplication safe.
 *
 * Skips when the workspace source is absent: the plugin is also mirrored to a
 * standalone git repo where `shared/` does not exist, and failing there would be
 * a false alarm. A skip is visible in the counts, unlike a silent pass.
 */
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

const PLUGIN_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const WORKSPACE_ROOT = resolve(PLUGIN_ROOT, '..');

/** shared source -> the copy this plugin ships. */
const SHARED = [['shared/define.js', 'lib/define.js']];

for (const [sourceRel, copyRel] of SHARED) {
  test(`${copyRel} matches ${sourceRel}`, (t) => {
    const sourcePath = join(WORKSPACE_ROOT, sourceRel);
    if (!existsSync(sourcePath)) {
      t.skip('workspace shared/ is not present (standalone checkout)');
      return;
    }
    const source = readFileSync(sourcePath, 'utf8');
    const copy = readFileSync(join(PLUGIN_ROOT, copyRel), 'utf8');
    assert.equal(
      copy,
      source,
      `${copyRel} has drifted from ${sourceRel}. Do not hand-edit the copy: ` +
        'run `node tools/sync-shared-code.mjs` in the workspace root to regenerate it.',
    );
  });
}
